/**
 * 表の DDL の migration 組み立て(`lib/sql/ddl-migration.ts`)のユニットテスト。
 *
 * 規約網羅(design/ddl-generation.md §0 / migrations.md §生成 migration):
 *   - 先頭に AUTO-GENERATED ヘッダと正の仕様ファイルが載る
 *   - **冪等**である —— 表は `create table if not exists`、列は `add column if not exists`、
 *     導出 CHECK は `drop constraint if exists` → `add constraint`、索引は
 *     `create index if not exists`、外部キーと排他制約は「まだ無いときだけ」の do ブロック
 *   - **列は足すだけ** —— `add column` に `not null` を付けない(データに触る判断は人)
 *   - 式の正が仕様に無い CHECK(`rule` も導出も無いもの)は作らないが、`invariant` を
 *     宣言するなら**存在を確かめてからコメントだけ**付ける
 *   - 排他制約があるときだけ `btree_gist` を要求し、期間は半開区間に固定する
 *   - RLS を有効にし、`comment on column` と `comment on constraint` を出す
 *   - トリガ関数は**誰の権限で実行するかを必ず字面に書く**(既定と同じ `security invoker` でも)
 *   - 中身が無い節は見出しごと出ない
 */

import { describe, expect, it } from 'vitest';
import { buildDdlMigration } from '../../../lib/sql/ddl-migration.js';
import type { TableDdlPlan } from '../../../lib/sql/ddl-plan.js';

/** 題材: 予約(booking)。呼び側が計画の一部だけを差し替えられる形にする。 */
function plan(overrides: Partial<TableDdlPlan> = {}): TableDdlPlan {
  return {
    table: 'bookings',
    entity: 'booking',
    primaryKey: ['id'],
    columns: [
      { name: 'id', type: 'uuid', notNull: true, default: 'gen_random_uuid()', identity: false, comment: null },
      { name: 'title', type: 'text', notNull: true, default: null, identity: false, comment: '件名' },
    ],
    derivedChecks: [
      { name: 'bookings_title_max_length', expression: '(char_length(title) <= 80)', invariant: null },
    ],
    declaredChecks: [],
    foreignKeys: [],
    indexes: [],
    exclusions: [],
    sequences: [],
    triggers: [],
    specFiles: ['docs/specs/domain/booking/entity.md', 'docs/specs/backend/data/tables/bookings.md'],
    ...overrides,
  };
}

describe('表の DDL の migration', () => {
  it('AUTO-GENERATED ヘッダに正の仕様ファイルが載る', () => {
    const sql = buildDdlMigration(plan());
    expect(sql).toContain('-- AUTO-GENERATED by `npm run generate` — 手編集禁止。');
    expect(sql).toContain('--   - docs/specs/domain/booking/entity.md');
    expect(sql).toContain('--   - docs/specs/backend/data/tables/bookings.md');
  });

  it('表と列と主キーを冪等に作る', () => {
    const sql = buildDdlMigration(plan());
    expect(sql).toContain('create table if not exists public.bookings (');
    expect(sql).toContain('    id uuid not null default gen_random_uuid(),');
    expect(sql).toContain('    title text not null,');
    expect(sql).toContain('    constraint bookings_pkey primary key (id)');
    expect(sql).toContain('alter table public.bookings add column if not exists title text;');
  });

  it('既にある列に足すときは not null を付けない(データに触る判断は人)', () => {
    const sql = buildDdlMigration(plan());
    const added = sql.split('\n').filter((line) => line.includes('add column if not exists'));
    expect(added).toEqual([
      'alter table public.bookings add column if not exists id uuid default gen_random_uuid();',
      'alter table public.bookings add column if not exists title text;',
    ]);
  });

  it('導出 CHECK は定義が違うときだけ drop → add する(定常状態では何もしない)', () => {
    const sql = buildDdlMigration(plan());
    // 無条件の drop → add は ACCESS EXCLUSIVE ロック + 全行検証なので、正準表記と突き合わせる。
    expect(sql).toContain(
      "and pg_get_constraintdef(c.oid) = 'CHECK ((char_length(title) <= 80))'",
    );
    expect(sql).toContain('alter table public.bookings drop constraint if exists bookings_title_max_length;');
    expect(sql).toContain(
      'alter table public.bookings add constraint bookings_title_max_length check (char_length(title) <= 80);',
    );
  });

  it('全域化した式は check の後ろでだけ括弧に包む(期待の字面は Postgres の印字どおり)', () => {
    const sql = buildDdlMigration(
      plan({
        declaredChecks: [
          {
            name: 'bookings_period_check',
            expression: 'COALESCE((starts_at < ends_at), false)',
            invariant: 'INV-BOOKING-002',
          },
        ],
      }),
    );
    // Postgres は COALESCE を括弧で包まずに印字するので、期待の側は包まない。
    expect(sql).toContain(
      "and pg_get_constraintdef(c.oid) = 'CHECK (COALESCE((starts_at < ends_at), false))'",
    );
    // `check` の直後には置けない形なので、そこだけ包む。
    expect(sql).toContain(
      'alter table public.bookings add constraint bookings_period_check ' +
        'check (COALESCE((starts_at < ends_at), false));',
    );
  });

  it('採番の器は表の DDL より前に出る(既定値の式がそれを呼ぶ)', () => {
    const sql = buildDdlMigration(
      plan({ sequences: [{ name: 'bookings_reference_seq', start: null }] }),
    );
    const sequenceAt = sql.indexOf('create sequence if not exists public.bookings_reference_seq;');
    const tableAt = sql.indexOf('create table if not exists public.bookings (');
    expect(sequenceAt).toBeGreaterThan(-1);
    // 後ろに置くと `create table` の既定値の regclass が解決できず、表そのものが作れない。
    expect(sequenceAt).toBeLessThan(tableAt);
  });

  it('採番の器は if not exists で、宣言した start だけを印字する', () => {
    const sql = buildDdlMigration(
      plan({
        sequences: [
          { name: 'a_seq', start: 1000 },
          { name: 'b_seq', start: null },
        ],
      }),
    );
    expect(sql).toContain('create sequence if not exists public.a_seq start with 1000;');
    expect(sql).toContain('create sequence if not exists public.b_seq;');
    // 表を落とさない方針と揃える(器も落とさない)。
    expect(sql).not.toContain('owned by');
    expect(sql).not.toContain('drop sequence');
  });

  it('器の宣言が無い表には create sequence を 1 行も出さない', () => {
    expect(buildDdlMigration(plan())).not.toContain('create sequence');
  });

  it('表の DDL は権限を 1 行も出さない(権限は系に 1 本の grants_migration が出す)', () => {
    // どの表でも同じ 1 組を表ごとのファイルに複製すると、仕組みの 1 行を変える日のコストが
    // 表数に比例する(実測 16 本)。組み立ては `grants-migration.ts` の持ち場である。
    const sql = buildDdlMigration(plan());
    expect(sql).not.toContain('revoke all on');
    expect(sql).not.toContain('grant ');
  });

  it('改変を拒否するトリガは関数ごと出て、まだ無いときだけ作る(drop → create にしない)', () => {
    const sql = buildDdlMigration(
      plan({
        triggers: [
          {
            name: 'bookings_append_only',
            fires: 'before update or delete',
            function: {
              name: 'reject_bookings_mutation',
              comment: '改変を拒否する。',
              body: ["raise exception 'no';"],
            },
          },
        ],
      }),
    );
    expect(sql).toContain('create or replace function public.reject_bookings_mutation() returns trigger');
    expect(sql).toContain("    raise exception 'no';");
    expect(sql).toContain("comment on function public.reject_bookings_mutation() is '改変を拒否する。';");
    // 存在ガード —— `drop trigger` を出すと、その間に拒否されるべき改変が通る。
    expect(sql).not.toContain('drop trigger');
    expect(sql).toContain("where t.tgrelid = 'public.bookings'::regclass and t.tgname = 'bookings_append_only'");
    expect(sql).toContain('        create trigger bookings_append_only');
    expect(sql).toContain('            execute function public.reject_bookings_mutation();');
  });

  it('誰の権限で実行するかを必ず字面に書く(既定と同じ invoker でも書く)', () => {
    const body = ["raise exception 'no';"];
    const invoker = buildDdlMigration(
      plan({
        triggers: [
          {
            name: 'g',
            fires: 'before insert',
            function: { name: 'fn', comment: 'c', body },
          },
        ],
      }),
    );
    const definer = buildDdlMigration(
      plan({
        triggers: [
          {
            name: 'g',
            fires: 'after insert',
            function: { name: 'fn', comment: 'c', body, securityDefiner: true },
          },
        ],
      }),
    );

    // `create or replace function` は指定しなかった属性を既定に戻すので、既定と同じ値でも
    // 書いておく —— 手書きの security definer を生成物に差し替えた日に静かに落ちる性質である。
    expect(invoker).toContain('language plpgsql\nsecurity invoker\nas $$');
    expect(invoker).not.toContain('set search_path');
    // 読み直すトリガだけが定義者の権限で走る(RLS の効いた接続から実行されると 0 行になる)。
    expect(definer).toContain('language plpgsql\nsecurity definer\nset search_path = public\nas $$');
    expect(definer).not.toContain('security invoker');
  });

  it('rule の CHECK は丸括弧に包まれた式で作られる(流せる SQL になる)', () => {
    const sql = buildDdlMigration(
      plan({
        derivedChecks: [],
        declaredChecks: [{ name: 'bookings_seats_positive', expression: '(seats > 0)', invariant: null }],
      }),
    );
    expect(sql).toContain(
      'alter table public.bookings add constraint bookings_seats_positive check (seats > 0);',
    );
  });

  it('式の正が仕様に無い CHECK は作らず、由来のコメントだけを存在を確かめて付ける', () => {
    const sql = buildDdlMigration(
      plan({
        derivedChecks: [],
        declaredChecks: [{ name: 'bookings_period_check', expression: null, invariant: 'INV-BOOKING-002' }],
      }),
    );
    expect(sql).not.toContain('add constraint bookings_period_check');
    // まだ無い DB でも流せるように、存在を確かめてからコメントを付ける。
    expect(sql).toContain("where c.conrelid = 'public.bookings'::regclass and c.conname = 'bookings_period_check'");
    expect(sql).toContain(
      "comment on constraint bookings_period_check on public.bookings is 'INV-BOOKING-002';",
    );
  });

  it('外部キーは「両方の表が在って、まだ無いときだけ」足す(名前ではなく列で判定する)', () => {
    const sql = buildDdlMigration(
      plan({
        foreignKeys: [
          {
            name: 'bookings_room_id_fkey',
            table: 'bookings',
            column: 'room_id',
            references: 'rooms',
            onDelete: 'no action',
          },
        ],
      }),
    );
    expect(sql).toContain("and pg_get_constraintdef(c.oid) like 'FOREIGN KEY (room_id)%'");
    expect(sql).toContain('alter table public.bookings add constraint bookings_room_id_fkey');
    expect(sql).toContain('foreign key (room_id) references public.rooms (id) on delete no action;');
    // **存在の確認は条件式の外側の `if` に出る。** このブロックは両側のファイルに出るので、
    // 先に当たる側では相手の表がまだ無く、`'…'::regclass` はその場で落ちる(`and` の評価順は
    // SQL が約束しないので、1 つの条件にまとめられない)。
    expect(sql).toContain(
      "    if to_regclass('public.bookings') is not null and to_regclass('public.rooms') is not null then",
    );
    expect(sql).toContain('        if not exists (');
  });

  it('外部キーは fk.table に張る(このファイルの表とは限らない)', () => {
    // 参照先の表のファイルにも同じブロックが出るので、制約を張る先は fk.table である。
    const sql = buildDdlMigration(
      plan({
        foreignKeys: [
          {
            name: 'members_invited_via_fkey',
            table: 'members',
            column: 'invited_via',
            references: 'invitations',
            onDelete: 'no action',
          },
        ],
      }),
    );
    expect(sql).toContain('alter table public.members add constraint members_invited_via_fkey');
    expect(sql).toContain("where c.conrelid = 'public.members'::regclass and c.contype = 'f'");
  });

  it('スキーマ修飾された参照先はそのまま使う', () => {
    const sql = buildDdlMigration(
      plan({
        foreignKeys: [
          { name: 'members_id_fkey', table: 'members', column: 'id', references: 'auth.users', onDelete: 'cascade' },
        ],
      }),
    );
    expect(sql).toContain('foreign key (id) references auth.users (id) on delete cascade;');
  });

  it('索引は if not exists で、部分索引は述語つき', () => {
    const sql = buildDdlMigration(
      plan({
        indexes: [
          { name: 'bookings_room_id_idx', columns: ['room_id', 'starts_at'], unique: false, where: null },
          { name: 'bookings_open_unique', columns: ['room_id'], unique: true, where: "state = 'open'" },
        ],
      }),
    );
    expect(sql).toContain(
      'create index if not exists bookings_room_id_idx on public.bookings (room_id, starts_at);',
    );
    expect(sql).toContain(
      "create unique index if not exists bookings_open_unique on public.bookings (room_id) where (state = 'open');",
    );
  });

  it('部分索引は定義を比べて作り直す(A14-3: 同じ名前のまま where を変えた DDL を黙って無視しない)。部分でない索引には出さない', () => {
    const sql = buildDdlMigration(
      plan({
        indexes: [
          { name: 'bookings_room_id_idx', columns: ['room_id'], unique: false, where: null },
          { name: 'bookings_open_unique', columns: ['room_id'], unique: true, where: "state = 'open'" },
        ],
      }),
    );
    expect(sql).toContain("if to_regclass('public.bookings_open_unique') is not null then");
    expect(sql).toContain('create temp table declared_index_probe (like public.bookings) on commit drop;');
    expect(sql).toContain("create unique index declared_index_probe_idx on pg_temp.declared_index_probe (room_id) where (state = 'open');");
    expect(sql).toContain("split_part(pg_get_indexdef('public.bookings_open_unique'::regclass), ' USING ', 2)");
    expect(sql).toContain('drop index public.bookings_open_unique;');
    expect(sql).toContain('drop table pg_temp.declared_index_probe;');
    expect(sql.indexOf('drop index public.bookings_open_unique;')).toBeLessThan(sql.indexOf('create unique index if not exists bookings_open_unique'));
    expect(sql).not.toContain('drop index public.bookings_room_id_idx');
    expect(sql.match(/create temp table/g)).toHaveLength(1);
  });

  it('排他制約があるときだけ btree_gist を要求し、期間は半開区間に固定する', () => {
    const without = buildDdlMigration(plan());
    expect(without).not.toContain('btree_gist');
    const sql = buildDdlMigration(
      plan({
        exclusions: [
          {
            name: 'bookings_room_slot_exclude',
            keys: ['room_id'],
            range: ['starts_at', 'ends_at'],
            where: "state <> 'cancelled'",
            invariant: 'INV-BOOKING-001',
          },
        ],
      }),
    );
    expect(sql).toContain('create extension if not exists btree_gist with schema extensions;');
    // スキーマ指定の無い形は出さない(A7-4。`public` に入り閉世界とぶつかる)。
    expect(sql).not.toMatch(/create extension if not exists btree_gist;/);
    expect(sql).toContain("and c.conname = 'bookings_room_slot_exclude'");
    expect(sql).toContain('room_id with =,');
    expect(sql).toContain("tstzrange(starts_at, ends_at, '[)') with &&");
    expect(sql).toContain(") where (state <> 'cancelled');");
    expect(sql).toContain(
      "comment on constraint bookings_room_slot_exclude on public.bookings is 'INV-BOOKING-001';",
    );
  });

  it('RLS を有効にし、列の説明と制約の由来をコメントに残す', () => {
    const sql = buildDdlMigration(
      plan({
        declaredChecks: [
          { name: 'bookings_seats_positive', expression: 'seats > 0', invariant: 'INV-BOOKING-004' },
        ],
      }),
    );
    expect(sql).toContain('alter table public.bookings enable row level security;');
    expect(sql).toContain("comment on column public.bookings.title is '件名';");
    expect(sql).not.toContain('comment on column public.bookings.id is');
    expect(sql).toContain(
      "comment on constraint bookings_seats_positive on public.bookings is 'INV-BOOKING-004';",
    );
  });

  it('由来を宣言する導出 CHECK にもコメントを付ける', () => {
    const sql = buildDdlMigration(
      plan({
        derivedChecks: [
          { name: 'bookings_title_max_length', expression: '(char_length(title) <= 80)', invariant: 'INV-B-9' },
        ],
      }),
    );
    expect(sql).toContain(
      "comment on constraint bookings_title_max_length on public.bookings is 'INV-B-9';",
    );
  });

  it('中身の無い節は見出しごと出ない', () => {
    const sql = buildDdlMigration(plan({ derivedChecks: [], columns: [], declaredChecks: [] }));
    expect(sql).not.toContain('外部キー');
    expect(sql).not.toContain('索引');
    expect(sql).not.toContain('排他制約');
    expect(sql).not.toContain('comment on');
  });
});
